<?php
require_once __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require_once __DIR__.'/learning_sharing_fixture.php';$f=learningSharingFixture($db,$f);
require_once __DIR__.'/../includes/learning_content_service.php';
$teacher=learningActor($db,$f['ids']['teacher']);$student=learningActor($db,$f['ids']['student_login']);$co=learningActor($db,$f['ids']['co_teacher']);
erpCheck(in_array('bank_kind',dbColumns($db,'questions'),true),'Separate question bank schema');
$chapter='Exam bank chapter';require_once __DIR__.'/../includes/curriculum_catalog.php';curriculumEnsureChapter($db,1,$f['class'],$f['subject'],$chapter);
$input=['class_id'=>$f['class'],'subject_id'=>$f['subject'],'chapter'=>$chapter,'type'=>'Short','question_text'=>'Confidential exam item','marks'=>5,'difficulty'=>'Hard','required_minutes'=>7,'cognitive_domain'=>'Application'];
$id=learningSaveQuestion($db,$teacher,$input,null,'exam');$row=$db->query('SELECT * FROM questions WHERE id='.$id)->fetch();
erpEqual($row['bank_kind'],'exam','Exam bank identity');erpEqual((int)$row['student_visible'],0,'Staff-only default');
erpEqual($row['difficulty'],'Hard','Difficulty separate from cognitive domain');erpEqual((float)$row['required_minutes'],7.0,'Required minutes');
erpCheck(learningCanView($db,$co,$row,'exam_bank'),'Assigned teacher sees exam private');
foreach(['study','practice','paper','bank'] as $purpose)erpEqual(learningCanView($db,$teacher,$row,$purpose),false,'Separate normal purpose '.$purpose);
erpEqual(learningCanView($db,$student,$row,'exam_view'),false,'Student no default access');
erpEqual(count(learningContentList($db,$teacher,'questions',[],'bank')),0,'Exam omitted from normal bank');
erpReject(fn()=>learningSaveQuestion($db,$teacher,$input,$id),'Normal route cannot edit exam record');
erpReject(fn()=>learningSaveQuestion($db,$co,$input,$id,'exam'),'Only creator edits exam');
erpReject(fn()=>learningSaveQuestion($db,$teacher,array_replace($input,['difficulty'=>'Extreme']),null,'exam'),'Invalid difficulty');
erpReject(fn()=>learningSaveQuestion($db,$teacher,array_replace($input,['required_minutes'=>0]),null,'exam'),'Required positive time');
learningSaveQuestion($db,$teacher,$input+['visibility'=>'public','student_visible'=>'1'],$id,'exam');$row=$db->query('SELECT * FROM questions WHERE id='.$id)->fetch();
erpCheck(learningCanView($db,$student,$row,'exam_view'),'Explicit released question visible in enrolled class');
erpEqual(learningCanView($db,$student,$row,'practice'),false,'Release does not mix practice bank');
erpEqual(count(learningContentList($db,$student,'questions',[],'exam_view')),1,'Student released list');
learningSaveQuestion($db,$teacher,$input+['visibility'=>'private','student_visible'=>'1'],$id,'exam');$row=$db->query('SELECT * FROM questions WHERE id='.$id)->fetch();
erpEqual((int)$row['student_visible'],0,'Private save revokes release');
erpEqual(learningCanView($db,$student,$row,'exam_view'),false,'Student view revoked immediately');
erpReject(fn()=>learningContentRecord($db,$student,'questions',$id,'exam_view',true),'Archived bypass cannot grant student access');
$fraction=learningSaveQuestion($db,$teacher,array_replace($input,['marks'=>'2.50','required_minutes'=>'3.25']),null,'exam');$row=$db->query('SELECT * FROM questions WHERE id='.$fraction)->fetch();
erpEqual((float)$row['marks'],2.5,'Exact decimal marks retained');erpEqual((float)$row['required_minutes'],3.25,'Exact required minutes retained');
echo 'Exam bank checks passed: '.$GLOBALS['erp_checks'].PHP_EOL;
